return UPDATE_TYPE.PRERELEASE;
}
return UPDATE_TYPE.UNKNOWN;
}
const diff = semver.diff(installed, latest);
if (diff === 'major') {
return UPDATE_TYPE.MAJOR;
}
if (diff === 'minor') {
return UPDATE_TYPE.MINOR;
}
if (diff === 'patch') {
return UPDATE_TYPE.PATCH;
}
if (diff === 'prerelease') {
return UPDATE_TYPE.PRERELEASE;
}
return UPDATE_TYPE.UNKNOWN;
}
